import React, { useState } from "react";
import Image from "next/image";
import Link from "next/link";
import "./AdminPage.css";

export default function AdminPage() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = (e) => {
    e.preventDefault();
    if (!username.trim() || !password.trim()) {
      setError("Por favor, completa todos los campos.");
      return;
    }
    setError("");
    setIsLoggedIn(true);
  };

  if (!isLoggedIn) {
    return (
      <div className="admin-container">
        {/* Header */}
        <header className="admin-header">
          <div className="header-content">
            <h1 className="header-title">TalkinPon</h1>
            <div className="header-center">
              <span className="header-subtitle">Inicio de sesión.</span>
            </div>
            <Link href="/">
              <Image
                src="/university-logo-circular.jpg"
                alt="Logo"
                width={60}
                height={60}
                className="header-logo"
              />
            </Link>
          </div>
        </header>

        {/* Login Form */}
        <main className="login-main">
          <div className="login-card">
            <h2 className="login-title">Bienvenido Administrador</h2>

            <form onSubmit={handleLogin} className="login-form">
              <div>
                <label htmlFor="username" className="login-label">
                  Usuario:
                </label>
                <input
                  type="text"
                  id="username"
                  value={username}
                  onChange={(e) => {
                    setUsername(e.target.value);
                    setError("");
                  }}
                  placeholder="Ingresa tu usuario..."
                  className="login-input"
                  required
                />
              </div>

              <div>
                <label htmlFor="password" className="login-label">
                  Contraseña:
                </label>
                <input
                  type="password"
                  id="password"
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    setError("");
                  }}
                  placeholder="Ingresa tu contraseña..."
                  className="login-input"
                  required
                />
              </div>

              {error && <div className="error-message">{error}</div>}

              <button type="submit" className="login-button">
                Iniciar sesión
              </button>
            </form>
          </div>
        </main>
      </div>
    );
  }

  return (
    <div className="admin-container">
      {/* Header */}
      <header className="admin-header">
        <div className="header-content">
          <h1 className="header-title">
            TalkinPon - Panel de Administrador
          </h1>
          <div className="header-actions">
            <button onClick={() => setIsLoggedIn(false)} className="logout-btn">
              Cerrar sesión
            </button>
            <Link href="/">
              <Image
                src="/university-logo-circular.jpg"
                alt="Logo"
                width={60}
                height={60}
                className="header-logo"
              />
            </Link>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="panel-main">
        <div className="panel-card">
          <h2 className="panel-title">
            Bienvenido al Panel de Administración, {username}
          </h2>

          <div className="panel-content">
            <p className="panel-description">
              Esta es la interfaz de administrador. Desde aquí podrás gestionar el sistema.
            </p>

            <div className="panel-grid">
              <div className="panel-item">
                <h3 className="panel-item-title">Gestión de Usuarios</h3>
                <p className="panel-item-text">Administrar usuarios del sistema</p>
              </div>

              <div className="panel-item">
                <h3 className="panel-item-title">Configuración</h3>
                <p className="panel-item-text">Ajustes del sistema</p>
              </div>

              <div className="panel-item">
                <h3 className="panel-item-title">Reportes</h3>
                <p className="panel-item-text">Ver estadísticas y reportes</p>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
